<?php
require_once __DIR__.'/../includes/functions.php';require_login();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$barang=(int)($_POST['barang_id']??0);$qty=(int)($_POST['qty']??0);$pelanggan=(int)($_POST['pelanggan_id']??0);$st=$pdo->prepare('SELECT * FROM barang WHERE id=?');$st->execute([$barang]);$b=$st->fetch();if(!$b||$qty<1||$qty>(int)$b['stok']){$error='Barang tidak ditemukan atau stok tidak mencukupi.';}else{$total=$qty*(float)$b['harga'];$pdo->beginTransaction();try{$st=$pdo->prepare('INSERT INTO transaksi (user_id,pelanggan_id,total,tanggal) VALUES (?,?,?,NOW())');$st->execute([$_SESSION['user_id'],$pelanggan?:null,$total]);$tid=$pdo->lastInsertId();$st=$pdo->prepare('INSERT INTO detail_transaksi (transaksi_id,barang_id,qty,harga) VALUES (?,?,?,?)');$st->execute([$tid,$barang,$qty,$b['harga']]);$st=$pdo->prepare('UPDATE barang SET stok=stok-? WHERE id=?');$st->execute([$qty,$barang]);$pdo->commit();header('Location: index.php?saved=1');exit;}catch(Throwable $e){$pdo->rollBack();$error='Transaksi gagal disimpan.';}}}
$items=$pdo->query('SELECT * FROM barang WHERE stok>0 ORDER BY nama_barang')->fetchAll();$customers=$pdo->query('SELECT * FROM pelanggan ORDER BY nama_pelanggan')->fetchAll();$recent=$pdo->query('SELECT t.*,u.nama AS petugas,p.nama_pelanggan FROM transaksi t JOIN users u ON u.id=t.user_id LEFT JOIN pelanggan p ON p.id=t.pelanggan_id ORDER BY t.id DESC LIMIT 20')->fetchAll();$page_title='Transaksi';require __DIR__.'/../includes/header.php';
?><div class="card"><h2>Transaksi Penjualan</h2><?php if(isset($_GET['saved'])):?><div class="alert success">Transaksi berhasil disimpan.</div><?php endif;?><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Barang</label><select name="barang_id" required><option value="">Pilih barang</option><?php foreach($items as $b):?><option value="<?=$b['id']?>"><?=e($b['nama_barang'])?> — Rp <?=number_format($b['harga'],0,',','.')?> (Stok: <?=$b['stok']?>)</option><?php endforeach;?></select><label>Pelanggan (opsional)</label><select name="pelanggan_id"><option value="">Umum</option><?php foreach($customers as $p):?><option value="<?=$p['id']?>"><?=e($p['nama_pelanggan'])?></option><?php endforeach;?></select><label>Jumlah</label><input type="number" name="qty" min="1" required><button type="submit">Simpan Transaksi</button></form></div><div class="card"><h3>Transaksi Terbaru</h3><div class="table-wrap"><table><tr><th>No</th><th>Tanggal</th><th>Petugas</th><th>Pelanggan</th><th>Total</th></tr><?php foreach($recent as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['tanggal'])?></td><td><?=e($r['petugas'])?></td><td><?=e($r['nama_pelanggan']??'Umum')?></td><td>Rp <?=number_format($r['total'],0,',','.')?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
